package com.example.com.englishai.backend.infrastructure.persistence.entity;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="conversation_scenario_definitions") public class ConversationScenarioDefinitionEntity { @Id private UUID id; @Column(nullable=false,unique=true,length=64) private String scenarioKey; @Column(nullable=false,length=120) private String displayName; @Column(nullable=false,length=500) private String description; @Column(nullable=false,length=120) private String assistantDisplayName; @Column(nullable=false,length=64) private String assistantAvatarKey; @Column(nullable=false,length=4000) private String behaviorInstructions; @Column(nullable=false) private boolean enabled; @Column(nullable=false) private int sortOrder; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected ConversationScenarioDefinitionEntity(){} public ConversationScenarioDefinitionEntity(UUID id,String key,String d,String desc,String ad,String aa,String behavior,boolean en,int order,OffsetDateTime now){this.id=id;scenarioKey=key;displayName=d;description=desc;assistantDisplayName=ad;assistantAvatarKey=aa;behaviorInstructions=behavior;enabled=en;sortOrder=order;createdAt=now;updatedAt=now;} public UUID getId(){return id;}public String getScenarioKey(){return scenarioKey;}public String getDisplayName(){return displayName;}public String getDescription(){return description;}public String getAssistantDisplayName(){return assistantDisplayName;}public String getAssistantAvatarKey(){return assistantAvatarKey;}public String getBehaviorInstructions(){return behaviorInstructions;}public boolean isEnabled(){return enabled;}public int getSortOrder(){return sortOrder;}public OffsetDateTime getCreatedAt(){return createdAt;}public OffsetDateTime getUpdatedAt(){return updatedAt;} public void update(String d,String desc,String ad,String aa,String b,boolean e,int o,OffsetDateTime t){displayName=d;description=desc;assistantDisplayName=ad;assistantAvatarKey=aa;behaviorInstructions=b;enabled=e;sortOrder=o;updatedAt=t;} public void disable(OffsetDateTime t){enabled=false;updatedAt=t;} }
